//! `morog completions <shell>` — emit a completion script to stdout.
//!
//! The script is generated by clap_complete from the clap definition in
//! `cli.rs`, so it always covers the current set of subcommands and flags.
//! The output is the raw script — the global `--format` flag is ignored
//! here. Dynamic value completion (citekeys, tag names) is future work;
//! the index could feed it.

use std::process::ExitCode;

use clap::CommandFactory;
use clap_complete::Shell;

use crate::cli::Cli;

pub fn run(shell: Shell) -> ExitCode {
    let mut cmd = Cli::command();
    clap_complete::generate(shell, &mut cmd, "morog", &mut std::io::stdout());
    ExitCode::SUCCESS
}
